<?php
/** 10,000 ORIGINAL SYNTHETIC records, only in the disposable cafcc_test database. */
if(DB_NAME!=='cafcc_test')throw new RuntimeException('Performance fixture requires disposable database.');
wp_set_current_user($admin);$qt=CAFCC_DB::table('questions');$qm=CAFCC_DB::table('question_meta');$ot=CAFCC_DB::table('occurrences');$tt=CAFCC_DB::table('question_tags');$rt=CAFCC_Studio::table();$base=CAFCC_Repository::get('questions',$facetq['id']);$initial=(int)$wpdb->get_var("SELECT COALESCE(MAX(id),0) FROM $qt")+1;$initial_occ=(int)$wpdb->get_var("SELECT COALESCE(MAX(id),0) FROM $ot")+1;
$timer=microtime(true);$hash=hash('sha256','TEST ORIGINAL performance source — no ICAI question text');$clean=CAFCC_Studio::clean($review_seed);$payload=wp_json_encode($clean);
for($batch=0;$batch<100;$batch++){
    $qvals=$mvals=$ovals=$tvals=$rvals=array();
    for($j=0;$j<100;$j++){$i=$batch*100+$j;$qid=$initial+$i;$oid=$initial_occ+$i;$key='TEST-PERF-'.$i;$reference='P'.$i;
        $qvals[]=$wpdb->prepare("(%d,%d,%d,%s,%s,'verified','published')",$qid,$base['document_id'],$base['chapter_id'],$reference,'TEST original performance fixture '.$i);
        $mvals[]=$wpdb->prepare("(%d,%s,%d,%d,'unknown')",$qid,$key,$fr['id'],$fr['subject_id']);
        $ovals[]=$wpdb->prepare("(%d,%s,%s,%d,%d,%d,%s,'','TEST original fixture','verified','published')",$oid,'O-'.$key,hash('sha256',$key),$qid,$base['document_id'],$fr['id'],$reference);
        $tvals[]=$wpdb->prepare("(%d,%d,'verified','published')",$qid,$t2['id']);
        $rvals[]=$wpdb->prepare("('subjective',%s,%d,%d,%s,%s,'TEST-PERF-SOURCE','FR','other','TEST only, no exam','original',%s,1,'approved','published',%s,'{}',%s,'TEST-PERFORMANCE',%s)",$key,$qid,$oid,$hash,hash('sha256',$hash.'|original|'.$reference.'|'),$reference,$payload,hash('sha256',$payload),current_time('mysql',true));
    }
    foreach(array("INSERT INTO $qt (id,document_id,chapter_id,question_number,title,verification_status,publication_status) VALUES ".implode(',',$qvals),"INSERT INTO $qm (question_id,stable_key,edition_id,primary_subject_id,question_type) VALUES ".implode(',',$mvals),"INSERT INTO $ot (id,occurrence_key,location_hash,question_id,document_id,edition_id,question_number,subquestion_number,page_reference,review_status,publication_status) VALUES ".implode(',',$ovals),"INSERT INTO $tt (question_id,node_id,review_status,publication_status) VALUES ".implode(',',$tvals),"INSERT INTO $rt (question_format,stable_id,question_id,occurrence_id,source_hash,source_identity,source_key,subject_code,source_type,exam_attempt,section_label,question_number,revision,status,publication_status,payload,approvals,payload_hash,batch_key,modified_at) VALUES ".implode(',',$rvals)) as $sql){if(false===$wpdb->query($sql))throw new RuntimeException('Synthetic performance fixture failed.');}
}
$load_ms=round((microtime(true)-$timer)*1000,1);wp_set_current_user($student_a);$start=microtime(true);$response=v4('GET','questions',null,array('search'=>'TEST-PERF','topic_id'=>$t2['id'],'page'=>250));$search_ms=round((microtime(true)-$start)*1000,1);$data=$response->get_data();check($response->get_status()===200&&$data['total']===10000&&count($data['items'])===20,'10,000 synthetic occurrence records are searched and only 20 results loaded on page 250');check(!str_contains(wp_json_encode($data),'review_question_text'),'Large student search does not load private review payloads');check($search_ms<10000,'Synthetic 10,000-row search completes inside the documented 10-second local test budget');
wp_set_current_user($admin);$start=microtime(true);$review=v4('GET','admin/reviews',null,array('search'=>'TEST-PERF','page'=>100));$studio_ms=round((microtime(true)-$start)*1000,1);$r=$review->get_data();check($review->get_status()===200&&$r['total']===10000&&count($r['items'])===50,'Review Studio handles 10,000 synthetic rows using 50-row server pagination');check($studio_ms<10000,'Large private Review Studio query stays inside the local test budget');
// Explicit version-3 upgrade snapshot: all existing original/connected/practice/account IDs survive.
function all_row_digest($table){global $wpdb;$ctx=hash_init('sha256');$offset=0;do{$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM $table ORDER BY 1 LIMIT 250 OFFSET %d",$offset),ARRAY_A);foreach($rows as $row)hash_update($ctx,wp_json_encode($row)."\n");$offset+=count($rows);}while(count($rows)===250);return array($offset,hash_final($ctx));}
$before=array();foreach(array($qt,$qm,$ot,$tt,$rt,CAFCC_Practice::table('notebook'),CAFCC_Practice::table('content'),CAFCC_DB::table('progress'),$wpdb->users) as $table)$before[$table]=all_row_digest($table);update_option('cafcc_db_version','3');check(true===CAFCC_DB::migrate(),'Populated v0.3 database upgrades to schema 4 without destructive migration');foreach($before as $table=>$rows)check($rows===all_row_digest($table),'Schema 4 retry preserves all fields and IDs in '.$table);
echo 'PERFORMANCE '.wp_json_encode(array('synthetic_occurrences'=>10000,'fixture_load_ms'=>$load_ms,'student_page_250_ms'=>$search_ms,'studio_page_100_ms'=>$studio_ms,'scope'=>'Disposable WordPress/MariaDB only; not a Hostinger latency or capacity guarantee.'))."\n";
